#include "rsr_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

#if RSR_ARM_ENA == 1
  #if !defined RSR_ARM_SET || !defined RSR_ARM_CLR
    #error !!!RSR_ARM_SET/CLR must be defined in DB3 core contract mapping!!!
  #endif									
#endif 

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rsr_arm (void * arg)
{
  #if RSR_ARM_ENA == 1	
	rsr_out_action (RSR_ARM_OUT, 0, rsr_opt.lock.dur, RSR_OUT_PAUSE, 1) ;
  #endif
}

//--------------------------------------------------------------------------//

void rsr_arm_timeout (void * arg)
{
  #if RSR_ARM_ENA == 1	
	  switch (rsr_out_ctl(RSR_ARM_OUT))
     {
		    case RSR_OUT_STATE_SET : RSR_ARM_SET ; break ;
        case RSR_OUT_STATE_CLR : RSR_ARM_CLR ; break ;
		    default: break ;
	   }
  #endif	 
}


